function countLargestGroup(n) {
  const groupSize = new Map();
  let largest = 0;
  for (let value = 1; value <= n; value++) {
    let digitSum = 0;
    for (let rest = value; rest > 0; rest = Math.floor(rest / 10)) {
      digitSum += rest % 10;
    }
    const size = (groupSize.get(digitSum) ?? 0) + 1;
    groupSize.set(digitSum, size);
    largest = Math.max(largest, size);
  }
  let count = 0;
  for (const size of groupSize.values()) {
    if (size === largest) {
      count++;
    }
  }
  return count;
}

