function countLargestGroup(n) {
  // Put the actual numbers into lists keyed by the digit sum of their decimal text.
  const groups = new Map();
  for (let x = 1; x <= n; x++) {
    const key = String(x).split('').reduce((sum, ch) => sum + Number(ch), 0);
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(x);
  }
  const lists = [...groups.values()];
  const biggest = Math.max(...lists.map(list => list.length));
  return lists.filter(list => list.length === biggest).length;
}

